import{c as t,Q as n,j as a,m as o}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Creating an event","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/create-event.md","filePath":"user/event-setup/create-event.md"}'),s={name:"user/event-setup/create-event.md"};function r(i,e,l,h,d,c){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="creating-an-event" tabindex="-1">Creating an event <a class="header-anchor" href="#creating-an-event" aria-label="Permalink to &quot;Creating an event&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers setting up a new competition in Manager.</p><p>How to create an event, edit its settings, and understand the options that shape how the event runs.</p><h2 id="the-events-page" tabindex="-1">The Events page <a class="header-anchor" href="#the-events-page" aria-label="Permalink to &quot;The Events page&quot;">​</a></h2><p>Open Manager and navigate to <strong>Events</strong> (this is where you land by default). The page has two tabs:</p><ul><li><strong>Upcoming</strong> — future and currently-running events, newest first.</li><li><strong>History</strong> — past and completed events, with a search field to filter by name.</li></ul><p>Each event is shown as a card with its name, date, and a coloured status chip — one of <strong>Setup mode</strong>, <strong>Event in progress</strong>, <strong>Event completed</strong>, or <strong>Event abandoned</strong>.</p><p>Clicking a card opens that event&#39;s dashboard. If you try to open a different event while another one is currently in progress, Manager asks you to confirm — the live event keeps running in the background.</p><p>A <a href="./multi-stage-events">multi-stage event</a> appears as a single row with its stages nested underneath; clicking the header opens the carnival&#39;s overview, and clicking a stage opens that stage&#39;s event like any other.</p><p>Hover over an event card to reveal two icons in the top-right corner: a download icon that exports a zip backup of the event, and a delete icon (red trash) that permanently removes it.</p><h2 id="creating-a-new-event" tabindex="-1">Creating a new event <a class="header-anchor" href="#creating-a-new-event" aria-label="Permalink to &quot;Creating a new event&quot;">​</a></h2><p>There are two ways to create an event:</p><ul><li><strong>New Event</strong> — creates an empty event with default settings. You then edit the details to fit your competition.</li><li><strong>New from Eventor</strong> — creates an event by importing from Eventor. See <a href="./create-event-from-eventor">Creating an event from Eventor</a>.</li></ul><h3 id="new-event" tabindex="-1">New Event <a class="header-anchor" href="#new-event" aria-label="Permalink to &quot;New Event&quot;">​</a></h3><p>Click <strong>New Event</strong> (top of the page, or in the welcome section if this is your first event). The <strong>New Event</strong> dialog asks what you&#39;re creating:</p><ul><li><strong>Individual</strong> — an ordinary event.</li><li><strong>Relay</strong> — a team event; reveals a <strong>Number of legs</strong> field (default 3).</li><li><strong>Multi-stage</strong> — a competition run across several events; asks only which <strong>kind</strong>: a <strong>Carnival</strong> (stages scored and added up) or a <strong>Knock-out</strong> (rounds whose field comes from the round before).</li></ul><p>Click <strong>Create</strong> and Manager creates it and opens it — an event at its dashboard, a multi-stage competition at its overview. A carnival arrives with three placeholder stages on consecutive days from today, which you then rename and re-date on its Stages tab; a knock-out arrives empty, because its rounds are generated from a template.</p><blockquote><p><strong>Note:</strong> The event type is fixed at creation and can&#39;t be changed later, and so is a multi-stage competition&#39;s kind. Most events are Individual; for team relays choose <strong>Relay</strong> — see <a href="./relay-events">Relay events</a>. A <strong>Multi-stage</strong> event isn&#39;t a third event type: it&#39;s a container whose stages are ordinary events, so nothing about running a stage changes — see <a href="./multi-stage-events">Multi-stage events</a> and <a href="./knock-out-competitions">Knock-out competitions</a>.</p></blockquote><p>The new event is in <strong>Setup</strong> mode and gets:</p><ul><li><strong>Name</strong> — today&#39;s day of the week (e.g. &quot;Thursday event&quot;).</li><li><strong>Date</strong> — today.</li><li><strong>Everything else</strong> — inherited from <strong>Settings → Event Defaults</strong> (start/finish unit numbers, event type, radio settings, etc.).</li></ul><p>You&#39;ll almost always want to change at least the name and date. Open the event details from the dashboard (see <a href="#editing-event-details">Editing event details</a> below) and edit anything you need to before adding competitors or going live.</p><blockquote><p><strong>Tip:</strong> The defaults are there to save you repeating the same choices event after event. If you find yourself changing the same field on every new event, set it in <a href="./../reference/settings">Settings → Event Defaults</a> instead.</p></blockquote><h2 id="editing-event-details" tabindex="-1">Editing event details <a class="header-anchor" href="#editing-event-details" aria-label="Permalink to &quot;Editing event details&quot;">​</a></h2><p>Once inside an event, click the edit icon on the <strong>Event header</strong> card (on the dashboard) to open the <strong>Event Details</strong> dialog. This is where you configure everything about how the event runs.</p><p>If the event was imported from Eventor, the dialog title shows an <strong>Eventor ID</strong> chip for traceability.</p><p>The dialog is organised into tabs down the left-hand side:</p><ul><li><a href="#details">Details</a> — name, date, description, classification</li><li><a href="#radio-controls">Radio Controls</a> — meshO Prime, SI codes for start/finish/check, radio-punch forwarding, SIRAP</li><li><a href="#starts">Starts</a> — mass start, punching-start override</li><li><a href="#auto-backup">Auto Backup</a> — periodic backups of the event</li><li><a href="#splits-print">Splits Print</a> — auto-print, QR code, per-event overrides</li><li><a href="#extensions">Extensions</a> — enable and configure installed extensions</li></ul><h3 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li><strong>Event name</strong> — editable at any time. Must be at least 3 characters.</li><li><strong>Event date</strong> — editable in Setup mode; <strong>locked once the event goes Live.</strong></li><li><strong>Description</strong> — optional free-text notes about the event.</li><li><strong>Event Type</strong> — Individual, Relay, etc. Affects how competitors and start times are organised.</li><li><strong>Competition Level</strong> — Local, National, etc. Currently informational; used by exports and reports.</li><li><strong>Discipline</strong> — the course length (Sprint, Middle, Long, Ultra Long) or the competition format (Knock Out Sprint, Sprint Relay, Mass Start, Pursuit, Relay, Mixed Relay, Qualification, PreO, TempO). Currently informational; used by exports and reports. Picking a relay discipline describes the race — it doesn&#39;t make the event a relay, which is what <strong>Event Type</strong> does.</li><li><strong>Course Format</strong> — what you flag the event as, and what a new course starts as. Each course can be changed on its own.</li><li><strong>Course Closure</strong> — optional. The time of day every competitor has to be back. Off unless you turn it on; when you do, the time defaults to 15:00:00. Once that time of day passes, Manager settles whoever nobody has accounted for — anyone still out is marked <strong>Overtime</strong>, anyone who never started <strong>DNS</strong>, and a radio finish with no card downloaded yet <strong>DNF</strong> — and a card downloaded afterwards whose finish punch was late is scored <strong>Overtime</strong> rather than <strong>OK</strong>. It never overrides a status you set yourself, and anyone marked Overtime with nothing to show they came back <strong>stays on the On Course list</strong>. See <a href="./../running-the-event/safety-check#course-closure-settling-the-list-at-a-set-time">Safety check</a>.</li></ul><h3 id="radio-controls" tabindex="-1">Radio Controls <a class="header-anchor" href="#radio-controls" aria-label="Permalink to &quot;Radio Controls&quot;">​</a></h3><p>This tab covers everything about radio-delivered punches.</p><p><strong>meshO Prime</strong> — toggle on if you have a meshO Prime radio network in the field. When on, Manager listens for radio punches from your Prime base unit.</p><p><strong>SI codes</strong> — radio punches carry only an SI control code (e.g. <code>2</code>), not a &quot;start&quot; / &quot;finish&quot; / &quot;check&quot;. Manager uses these fields to know what each code means at this event. Any code not listed here is treated as a regular radio control along a course.</p><ul><li><strong>Start Codes</strong> — SI codes of your start units.</li><li><strong>Finish Codes</strong> — SI codes of your finish units.</li><li><strong>Check Codes</strong> — SI codes of your check units.</li></ul><p>Enter one or more codes per field, comma-separated. The same code can&#39;t appear in more than one field. These remain editable during the event.</p><p><strong>Forward Radio Punches</strong> (visible only when meshO Prime is on) — forwards each incoming radio punch to the destinations configured in <strong>Settings → Radio Punch Forwarding</strong>.</p><p><strong>Accept SIRAP Punches</strong> — accept incoming SIRAP-protocol punches from external sources.</p><h3 id="starts" tabindex="-1">Starts <a class="header-anchor" href="#starts" aria-label="Permalink to &quot;Starts&quot;">​</a></h3><p><strong>Mass Start</strong> — toggle on if all or most competitor starts at the same time. When on, set the <strong>Mass Start Time</strong>. Defaults to 10:00:00 the first time you enable it.</p><p><strong>Allow punching starts to override allocated starts</strong> — if a competitor punches a start unit, use that punch as their start time even if they had an allocated start time. Turn off if your event uses strict allocated starts only. This can also be overriden for each competitor, if required.</p><h3 id="auto-backup" tabindex="-1">Auto Backup <a class="header-anchor" href="#auto-backup" aria-label="Permalink to &quot;Auto Backup&quot;">​</a></h3><p><strong>Enable auto backup</strong> — when on, Manager periodically writes a zip backup of the event to an <code>auto-backup/</code> directory inside the event&#39;s folder while the event is running. You can restore from these zips with the standard restore-from-backup flow.</p><p><strong>Backup frequency</strong> — how often to take a backup (e.g. every 15 minutes).</p><h3 id="splits-print" tabindex="-1">Splits Print <a class="header-anchor" href="#splits-print" aria-label="Permalink to &quot;Splits Print&quot;">​</a></h3><p>Per-event overrides for the global splits-printer settings configured in <strong>Settings → Splits Printer</strong>.</p><ul><li><strong>Automatic print splits on download</strong> — use the global setting, force on, or force off for this event.</li><li><strong>Disable meshO logo on print</strong> — use the global setting, force on, or force off for this event.</li></ul><p><strong>QR code</strong> — a QR code printed at the bottom of each competitor&#39;s splits, generated from a URL template. Three modes:</p><ul><li><strong>Use global setting</strong> — uses the template from <strong>Settings → Splits Printer</strong>.</li><li><strong>Customise for this event</strong> — set a URL template just for this event. Supported placeholders: <code>{competitorId}</code>, <code>{eventId}</code>, <code>{cardNumber}</code>. A <strong>Use this server&#39;s spectator URL</strong> button fills in a sensible default. You can also set a custom caption printed below the code.</li><li><strong>Disable for this event</strong> — no QR code is printed, regardless of the global setting.</li></ul><h3 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions&quot;">​</a></h3><p>Each installed extension appears with a switch. Enabling an extension reveals its per-event configuration fields (extensions can also have app-wide configuration set on the Extensions page).</p><p>If no extensions are installed, the tab shows a hint pointing to the Extensions page.</p><h2 id="deleting-an-event" tabindex="-1">Deleting an event <a class="header-anchor" href="#deleting-an-event" aria-label="Permalink to &quot;Deleting an event&quot;">​</a></h2><p>On the <strong>Events</strong> page, hover over an event card and click the red trash icon. Confirm the prompt. This permanently removes the event and all its data. There is no undo.</p><h2 id="what-s-locked-when-the-event-is-in-progress" tabindex="-1">What&#39;s locked when the event is in progress <a class="header-anchor" href="#what-s-locked-when-the-event-is-in-progress" aria-label="Permalink to &quot;What&#39;s locked when the event is in progress&quot;">​</a></h2><p>Once you click <strong>Start event</strong>, the <strong>event date</strong> becomes read-only. Changing the date of a running event would invalidate time calculations.</p><p>Everything else — name, description, classification, radio settings, unit codes, starts configuration, competitors, classes, courses, start times — remains editable throughout the event.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./create-event-from-eventor">Creating an event from Eventor</a> — the one-step alternative</li><li><a href="./multi-stage-events">Multi-stage events</a> — a carnival scored across several events</li><li><a href="./import-event-data">Importing event data</a> — the usual next step after creating an event</li><li><a href="./classes-and-courses">Classes and courses</a></li><li><a href="./../getting-started/first-event-walkthrough">Walkthrough: your first event</a> — the quick version</li><li><a href="./../reference/settings">Settings</a> — where Event Defaults are configured</li></ul>',58)])])}const p=t(s,[["render",r]]);export{u as __pageData,p as default};
